def nth_highest(employee: pd.DataFrame, n: int = 2) -> pd.DataFrame:
    unique_salaries = employee["salary"].drop_duplicates().sort_values(ascending=False).reset_index(drop=True)
    if len(unique_salaries) < n:
        return pd.DataFrame({"SecondHighestSalary": [None]})
    return pd.DataFrame({"SecondHighestSalary": [unique_salaries.iloc[n - 1]]})

