import pandas as pd

def find_customers(customers: pd.DataFrame, orders: pd.DataFrame) -> pd.DataFrame:
    if customers.empty:
        return pd.DataFrame(columns=['Customers'])
    if orders.empty or 'customerId' not in orders.columns:
        return customers[['name']].rename(columns={'name': 'Customers'})
    valid_orders = orders.dropna(subset=['customerId'])
    never = customers[~customers['id'].isin(valid_orders['customerId'])]
    return never[['name']].rename(columns={'name': 'Customers'})

