def find_employees(employee: pd.DataFrame) -> pd.DataFrame:
    if employee.empty:
        return pd.DataFrame(columns=['Employee'])
    emp = employee.dropna(subset=['managerId']).copy()
    emp['managerId'] = emp['managerId'].astype(employee['id'].dtype)
    merged = emp.merge(employee, left_on='managerId', right_on='id', suffixes=('_emp', '_mgr'))
    res = merged[merged['salary_emp'] > merged['salary_mgr']]
    return res[['name_emp']].rename(columns={'name_emp': 'Employee'})

