def human_traffic(stadium: pd.DataFrame) -> pd.DataFrame:
    filtered = stadium[stadium['people'] >= 100].copy()
    if filtered.empty:
        return pd.DataFrame(columns=['id', 'visit_date', 'people'])
    filtered['grp'] = filtered['id'] - range(len(filtered))
    counts = filtered.groupby('grp')['id'].transform('count')
    valid = filtered[counts >= 3]
    return valid[['id', 'visit_date', 'people']].sort_values(by='id')

import pandas as pd

def find_managers(employee: pd.DataFrame) -> pd.DataFrame:
    if employee.empty:
        return pd.DataFrame(columns=['name'])
    emp = employee.dropna(subset=['managerId']).copy()
    if emp.empty:
        return pd.DataFrame(columns=['name'])
    emp['managerId'] = emp['managerId'].astype(employee['id'].dtype)
    counts = emp.groupby('managerId').size().reset_index(name='report_count')
    eligible = counts[counts['report_count'] >= 5]
    res = eligible.merge(employee, left_on='managerId', right_on='id')
    return res[['name']]

